def f(g):
    import numpy as np
    a=np.array(g); H,W=a.shape
    # find block: most common nonzero color forming a rectangle
    cols,counts=np.unique(a[a!=0],return_counts=True)
    bc=cols[np.argmax(counts)]
    mask=a==bc
    rs,cs=np.where(mask)
    r0,r1,c0,c1=rs.min(),rs.max(),cs.min(),cs.max()
    out=a.copy()
    dot=(a!=0)&(a!=bc)
    dotrows=set(); dotcols=set()
    for r,c in zip(*np.where(dot)):
        if r0<=r<=r1 and not (c0<=c<=c1): dotrows.add(r)
        if c0<=c<=c1 and not (r0<=r<=r1): dotcols.add(c)
    for r in range(r0,r1+1):
        for c in range(0,c1+1):
            if a[r,c]==0: out[r,c]=bc
        if r not in dotrows:
            for c in range(c1+1,W):
                if a[r,c]==0: out[r,c]=bc
    for c in range(c0,c1+1):
        if c not in dotcols:
            for r in range(r1+1,H):
                if a[r,c]==0: out[r,c]=bc
    return out.tolist()
