def f(g):
    import numpy as np
    a=np.array(g); H,W=a.shape
    cols,counts=np.unique(a[a!=0],return_counts=True)
    bc=cols[np.argmax(counts)]
    rs,cs=np.where(a==bc)
    r0,r1,c0,c1=rs.min(),rs.max(),cs.min(),cs.max()
    out=a.copy()
    dot=(a!=0)&(a!=bc)
    def ray(r,c,dr,dc):
        rr,cc=r+dr,c+dc
        cells=[]
        while 0<=rr<H and 0<=cc<W:
            cells.append((rr,cc)); rr+=dr; cc+=dc
        return cells
    for r in range(r0,r1+1):
        for dc in (-1,1):
            cells=ray(r,c0 if dc<0 else c1,0,dc)
            if any(dot[p] for p in cells): continue
            for rr,cc in cells:
                if a[rr,cc]==0: out[rr,cc]=bc
    for c in range(c0,c1+1):
        for dr in (-1,1):
            cells=ray(r0 if dr<0 else r1,c,dr,0)
            if any(dot[p] for p in cells): continue
            for rr,cc in cells:
                if a[rr,cc]==0: out[rr,cc]=bc
    return out.tolist()
